"""Public legal texts and the exact consent snapshot used by the SMTP handler."""
import hashlib
import html

REVISION = '22 октября 2026 года'
PRIVACY_REVISION = '27 октября 2026 года'


def consent_document(site):
    text = f'''Согласие на обработку персональных данных
Редакция: {REVISION}.

Я свободно, своей волей и в своём интересе даю согласие на обработку моих персональных данных, указанных в форме на {site['domain']}/. Оператор: {site['legalName']} (ИНН {site['inn']}, ОГРН {site['ogrn']}, адрес: {site['legalAddress']}).

Цель: ответ на моё обращение, обсуждение потребности в оборудовании, подбор комплектации, подготовка технических требований и индивидуального предложения, согласование возможной поставки.

Данные: имя и телефон; если я их указываю — электронная почта, организация, сведения обо мне в описании задачи и прикреплённом файле. Согласие относится к моим данным; оно не даёт права передавать сведения о других людях без законного основания.

Действия: сбор, запись, систематизация, накопление, хранение, уточнение, извлечение, использование для ответа, предоставление доступа уполномоченным работникам и привлечённым для обработки заявки провайдерам хостинга REG.RU и почты Mail.ru, блокирование, удаление и уничтожение. Обработка выполняется с использованием средств автоматизации и без них. Содержание заявки направляется на {site['email']}. Публикация данных в открытом доступе и использование для рекламных рассылок в это согласие не входят.

Согласие действует до завершения рассмотрения обращения, но не более {site['leadRetentionDays']} календарных дней с даты отправки заявки, либо до моего отзыва, если он поступит раньше. После прекращения обработки данные удаляются в течение 30 дней, если отсутствует самостоятельное законное основание для их дальнейшей обработки. При заключении договора необходимые для него сведения обрабатываются на соответствующем законном основании; это не продлевает согласие на неопределённый срок.

Отозвать согласие можно письмом на {site['email']} с темой «Отзыв согласия» или письменным обращением по адресу оператора. Для поиска обращения достаточно указать использованные при отправке контакты; при необходимости оператор проверяет личность заявителя в установленном законом порядке.

Я предоставляю это согласие отдельным действием — отмечаю изначально пустой флажок «Даю согласие на обработку моих персональных данных для ответа на обращение» и отправляю форму. Согласие не объединяется с принятием условий покупки или подпиской на рекламу.
'''
    digest = hashlib.sha256(text.encode('utf-8')).hexdigest()
    return {'version': 'request-2026-10-22-' + digest[:12], 'sha256': digest,
            'text': text, 'form_enabled': bool(site.get('contactFormEnabled', False))}


def privacy_content(site, provider, counter, form_enabled=None):
    name, address = html.escape(site['legalName']), html.escape(site['legalAddress'])
    email = html.escape(site['email'])
    form_enabled = bool(site.get('contactFormEnabled')) if form_enabled is None else form_enabled
    has_form = provider == 'smtp' and form_enabled
    status = ('<p>На основном сайте доступна форма обращения с отдельным согласием.</p>' if has_form else '<p>На этой странице нет формы для отправки контактных данных и вложений. Онлайн-форма временно недоступна; её отключение не исключает обработку обращений, поступающих по телефону или электронной почте.</p>')
    if provider != 'smtp':
        status = '<p>Вы просматриваете публичную статическую копию сайта на GitHub Pages. Эта копия не содержит формы и не принимает заявки или вложения через браузер.</p>'
        if not form_enabled:
            status += '<p>Онлайн-форма временно недоступна. Контакты компании доступны в разделе <a href="/contacts/">«Контакты»</a>.</p>'
        status += '<p>GitHub получает IP-адрес посетителя и технические сведения при загрузке страниц, в том числе для безопасности сервиса. Это происходит независимо от наличия формы или аналитики. Обработку осуществляет GitHub по своей <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" rel="noopener noreferrer" target="_blank">политике конфиденциальности</a>; сервис может обрабатывать сведения за пределами РФ. Сроки и условия обработки технических журналов GitHub определяет самостоятельно. «Лигус» не передаёт GitHub содержание обращений из своей почты.</p>'
    form_purpose = ''
    form_flow = ''
    form_security = ''
    form_retention = ''
    form_consent = ''
    if has_form:
        form_purpose = '<h3>Обращение через форму</h3><p>Обрабатываем имя и телефон; по желанию заявителя — электронную почту, организацию, описание задачи и файл. Цели: ответ на обращение, уточнение потребности, подбор комплектации, подготовка технических требований и предложения, согласование поставки. Основание — отдельное <a href="/consent/">согласие</a> по пункту 1 части 1 статьи 6 Федерального закона № 152-ФЗ. Отказ от согласия не ограничивает просмотр сайта; отправить данные через форму без согласия нельзя.</p>'
        form_flow = '<p>Заявка поступает на сервер основного сайта в REG.RU и передаётся через почтовый сервер в ящик Mail.ru. Обработчик не создаёт отдельный архив содержания заявок; загруженное вложение временно обрабатывается на сервере и удаляется после попытки отправки.</p>'
        form_security = '<p>Форма использует HTTPS, защитный токен, проверку источника запроса, полей, согласия и формата файла, ограничение частоты запросов. Для защиты от спама и повторной отправки обрабатываются хеш IP-адреса, время и статус запроса. Основание — пункт 7 части 1 статьи 6 закона № 152-ФЗ при соблюдении прав посетителей. Конфигурация почты и временное хранилище расположены вне публичной папки сайта; содержание формы не сохраняется в техническую базу или хранилище браузера.</p>'
        form_retention = '<p>Временное вложение удаляется после попытки отправки. Файлы, оставшиеся после сбоя, старше часа удаляются обслуживанием обработчика. При обслуживании записи ограничения частоты удаляются после часа, состояния повторной отправки — после двух часов. Эти сроки относятся к техническому хранилищу обработчика, а не к журналам хостинга или почтовому ящику.</p>'
        form_consent = '<p>Флажок согласия изначально пуст и не объединяется с условиями покупки или подпиской на рекламу. Вместе с заявкой в почте сохраняются текст, версия и контрольная сумма согласия, идентификатор и время отправки. Они подтверждают согласие; срок их хранения связан с соответствующим обращением и законным основанием обработки.</p>'
    analytics = ('<p>Яндекс Метрика загружается только после отдельного выбора посетителя. Отказ не препятствует обращению. Счётчик получает технические сведения о посещении и действиях на сайте; поля формы и вложения не передаются в события, Вебвизор отключён. Выбор сохраняется в localStorage браузера на 180 дней; его можно изменить по ссылке «Файлы cookie» в подвале.</p>' if counter else '<p>Аналитические и рекламные счётчики «Лигус» отключены. Код сайта не устанавливает аналитические cookie и не записывает выбор аналитики в хранилище браузера. Шрифты, изображения и скрипты загружаются с этого сайта. В подвале по ссылке «Файлы cookie» можно проверить текущий статус. Нажимать «согласен» для просмотра страниц не требуется.</p>')
    return f'''<p class="legal-revision">Редакция от {PRIVACY_REVISION}</p>
<h2>Оператор и область действия</h2><p>Оператор — {name}, ИНН {site['inn']}, КПП {site['kpp']}, ОГРН {site['ogrn']}. Адрес: {address}. По вопросам персональных данных: <a href="mailto:{email}">{email}</a>.</p><p>Политика относится к посетителям сайта, заявителям, покупателям и представителям организаций, которые обращаются за подбором и поставкой оборудования. Она описывает обработку обращений и технических сведений о работе сайта. Просмотр политики не является согласием на обработку данных.</p>{status}
<h2>Цели, данные и основания обработки</h2>{form_purpose}
<h3>Обращения по электронной почте и телефону</h3><p>При обращении используются сообщённые вами имя, контактные сведения, организация, содержание вопроса и предоставленные документы. Цель — ответить, уточнить потребность в оборудовании, подготовить индивидуальное предложение и согласовать поставку. Для заключения договора по инициативе самого гражданина применяется пункт 5 части 1 статьи 6 закона № 152-ФЗ. Деловая переписка с представителями организаций в необходимом объёме основывается на законном интересе в ответе на инициированное ими обращение при соблюдении их прав — пункт 7 части 1 статьи 6. Если для обработки требуется согласие, его запрашивают отдельно; отправка письма сама по себе не считается согласием на любые цели.</p><p>Не направляйте паспортные данные, сведения о здоровье, платёжных картах или лишние сведения о других людях. Специальные категории и биометрические данные для подбора оборудования не запрашиваются. Для дополнительных сведений определяются конкретная цель и законное основание.</p>
<h3>Договор, покупка и обращения о качестве</h3><p>При заключении и исполнении договора с физическим лицом необходимые имя, контакты, адрес доставки, сведения о заказе, оплате и требованиях покупателя обрабатываются по пункту 5 части 1 статьи 6 закона № 152-ФЗ. Исполнение обязанностей по учёту расчётов и рассмотрению требований покупателей — по пункту 2 части 1 статьи 6. Договор с организацией сам по себе не является согласием её работника. Для доставки конкретного заказа получатель данных, их необходимый состав и основание передачи определяются до передачи перевозчику.</p>
<h3>Запросы о персональных данных</h3><p>Для рассмотрения запроса используются ваши контакты, сведения, позволяющие найти обращение и при необходимости проверить личность или полномочия, содержание требования и ответа. Цель — исполнить обязанности оператора и обеспечить права субъекта по статьям 14, 20 и 21 закона № 152-ФЗ. Основание — пункт 2 части 1 статьи 6. Необходимость и срок сохранения ответа определяются исполнением этих обязанностей; сведения, для которых основание отсутствует, уничтожаются.</p>
<h3>Работоспособность и безопасность сайта</h3><p>При сетевом обращении хостинг получает IP-адрес, дату и время, адрес запрошенной страницы, код ответа и сведения о браузере. Эти сведения используются для доставки страниц и защиты от технических сбоев и злоупотреблений. Для необходимой обработки со стороны «Лигус» основание — законный интерес в работоспособности и защите сайта при соблюдении прав посетителей, пункт 7 части 1 статьи 6 закона № 152-ФЗ. Состав и сроки технических журналов хостинга зависят от условий соответствующего провайдера; сроки временных записей формы не распространяются на эти журналы.</p>{form_security}
<h2>Порядок обработки и получатели</h2><p>Обработка выполняется с использованием автоматизации и без неё: сбор, запись, систематизация, накопление, хранение, уточнение, извлечение, использование, предоставление необходимого доступа, блокирование, удаление и уничтожение. Доступ работников ограничивается необходимостью работы с обращением. Полученные письма и вложения хранятся в ящике Mail.ru <a href="mailto:{email}">{email}</a>. Основной сайт размещён в REG.RU. При поручении обработки провайдеру должны быть обеспечены условия части 3 статьи 6 закона № 152-ФЗ.</p>{form_flow}<p>Содержание обращений не публикуется, не направляется в FormSubmit и не передаётся для сторонних рекламных рассылок. Передача государственным органам осуществляется только при предусмотренном законом основании. Решения, порождающие юридические последствия для заявителя, исключительно на основании автоматизированной обработки не принимаются.</p>
<h2>Локализация и передача за пределы РФ</h2><p>При сборе персональных данных граждан РФ запись, систематизация, накопление, хранение, уточнение и извлечение должны выполняться с соблюдением части 5 статьи 18 закона № 152-ФЗ. Трансграничная передача требует самостоятельного законного основания и выполнения статьи 12, включая отдельное уведомление Роскомнадзора в предусмотренном порядке. Описание иностранного хостинга в этой политике не заменяет этих требований. Содержание обращений не направляется через зарубежные сервисы сбора заявок.</p>
<h2>Сроки хранения и уничтожение</h2><p>Обращение о подборе оборудования без договора обрабатывается до завершения обсуждения, но не более {site['leadRetentionDays']} календарных дней с даты поступления. Для продолжения после этого срока требуется новое законное основание. После достижения цели или отзыва согласия данные удаляются в течение 30 дней при отсутствии другого основания. Договорные, бухгалтерские и иные обязательные документы хранятся в сроки применимого законодательства; это не означает бессрочное хранение всех обращений.</p>{form_retention}<p>Письма, вложения, копии на рабочих устройствах и резервные копии входят в порядок хранения и уничтожения оператора. Удалению подлежат ненужные рабочие копии и содержимое корзины; резервные копии исключаются из обычного использования и удаляются с соблюдением применимых сроков. Уничтожение должно подтверждаться в порядке приказа Роскомнадзора от 28.10.2022 № 179. При невозможности уничтожения в установленный законом срок данные блокируются и уничтожаются в срок не более шести месяцев, если иной срок не установлен федеральным законом, согласно части 6 статьи 21 закона № 152-ФЗ.</p>
<h2>Согласие и ваши права</h2>{form_consent}<p>Вы вправе получить сведения об обработке и ознакомиться с данными, потребовать их уточнения, блокирования, уничтожения или прекращения обработки в предусмотренных законом случаях, отозвать согласие и обжаловать действия оператора в <a href="https://rkn.gov.ru/" rel="noopener noreferrer" target="_blank">Роскомнадзоре</a> или суде. Согласие на ответ по обращению не разрешает рекламные рассылки.</p><p>Направьте требование или отзыв на <a href="mailto:{email}">{email}</a> либо по адресу оператора. Для поиска обращения укажите использованные контакты и суть требования. Подтверждение личности или полномочий запрашивается только при необходимости и в установленном законом объёме.</p><p>Сведения об обработке предоставляются в течение 10 рабочих дней; мотивированное продление возможно ещё на 5 рабочих дней. Подтверждённые неточные данные исправляются в течение 7 рабочих дней. Требование прекратить обработку исполняется в течение 10 рабочих дней, с предусмотренным законом продлением не более чем на 5 рабочих дней и исключениями статьи 21. При выявлении неправомерной обработки она прекращается в течение 3 рабочих дней; если обеспечить правомерность невозможно, данные уничтожаются в течение 10 рабочих дней с выявления. Отзыв согласия не прекращает обработку, для которой сохраняется самостоятельное законное основание.</p>
<h2>Защита данных</h2><p>Для загрузки сайта используется HTTPS. Защита обращений предусматривает ограничение и разграничение доступа, конфиденциальность работников, контроль обработки, безопасное хранение и уничтожение. Внутренние сведения о конфигурации защиты и секреты не публикуются. По вопросам безопасности и обработки можно обратиться к оператору по контактам выше.</p>
<h2 id="cookies">Файлы cookie и аналитика</h2>{analytics}<p>Отключение счётчиков не исключает техническую обработку запросов хостингом, описанную выше. Настройки браузера позволяют управлять сохранёнными данными; использование сайта не означает согласия на рекламу или необязательную аналитику.</p>
<h2>Изменения политики</h2><p>Актуальная редакция доступна на этой странице. Изменение политики не расширяет ранее предоставленное согласие: для новых целей или состава данных требуется соответствующее правовое основание.</p>'''


def buyer_content(site):
    name, address = html.escape(site['legalName']), html.escape(site['legalAddress'])
    returns = html.escape(site['returnsAddress'])
    email, hours = html.escape(site['email']), html.escape(site['workingHours'])
    return f'''<p class="legal-revision">Редакция от {REVISION}</p>
<h2>Продавец</h2><p>{name}. ИНН {site['inn']}, КПП {site['kpp']}, ОГРН {site['ogrn']}. Адрес: {address}. Режим работы: {hours}. Электронная почта: <a href="mailto:{email}">{email}</a>, телефон: <a href="tel:{site['phoneHref']}">{site['phone']}</a>.</p>
<h2>Подбор и оформление покупки</h2><p>Сайт знакомит с направлениями поставок. Отправка обращения означает запрос на подбор и расчёт; она не оформляет заказ, не резервирует товар и не создаёт обязанности оплатить его. Конкретные модель, комплектация, количество, цена в рублях, наличие, срок действия предложения и условия приобретения указываются в индивидуальном предложении до заключения договора.</p><p>До покупки предоставляем сведения о потребительских свойствах, изготовителе и месте изготовления товара, сроке службы и гарантии, если они установлены, правилах эксплуатации и обязательном подтверждении соответствия. При дистанционной продаже товара, подлежащего обязательному подтверждению соответствия, его описание должно содержать ссылку на запись о сертификате или декларации в соответствующем реестре. Включение модели в реестр российской промышленной продукции не заменяет сертификат или декларацию соответствия.</p>
<h2>Оплата и доставка</h2><p>Способ и порядок оплаты, стоимость доставки, адрес, срок и условия передачи товара согласовываются до заключения договора и фиксируются в предложении или договоре. Сайт не принимает платежи и не запрашивает реквизиты банковской карты. Кассовый чек предоставляется в случаях и порядке, установленных Федеральным законом № 54-ФЗ. Расчётный документ банка не заменяет кассовый чек, когда он обязателен.</p><p>Доставка по России и в страны СНГ рассчитывается для конкретного заказа. Возможность доставки в выбранный населённый пункт и дополнительные услуги подтверждаются до оплаты.</p>
<h2>Покупки физическими лицами</h2><p>Если товар приобретается гражданином для личных, семейных, домашних и иных нужд, не связанных с предпринимательской деятельностью, применяются Закон РФ «О защите прав потребителей» и обязательные правила розничной продажи. Условия индивидуального предложения не ограничивают предусмотренные законом права покупателя.</p>
<h3>Отказ от товара надлежащего качества при дистанционной покупке</h3><p>Покупатель вправе отказаться от товара до передачи, а после передачи — в течение семи дней. Если сведения о порядке и сроках возврата не предоставлены в письменной форме при доставке, срок отказа составляет три месяца с передачи. Для возврата должны быть сохранены товарный вид и потребительские свойства. Отсутствие чека само по себе не исключает возможность подтвердить покупку другими доказательствами.</p><p>Исключение — товар надлежащего качества с индивидуально-определёнными свойствами, который может использоваться исключительно приобретающим его покупателем. Сам по себе подбор стандартной комплектации или статус технически сложного товара не означает автоматического запрета дистанционного возврата.</p><p>Об отказе и возврате можно сообщить на <a href="mailto:{email}">{email}</a> или направить письменное требование по адресу: {returns}. Укажите сведения о покупке, товаре и требовании. Возврат возможен дистанционно, в том числе через перевозчика или почту, способом, позволяющим проверить состояние товара при получении. Для уточнения получателя и режима приёма можно связаться с нами; предварительное согласование не является условием осуществления законного права на возврат.</p><p>При отказе от товара надлежащего качества уплаченная сумма возвращается не позднее десяти дней со дня предъявления соответствующего требования, за исключением предусмотренных законом расходов продавца на доставку возвращённого товара от покупателя. Риск транспортировки и расходы на дистанционный возврат такого товара несёт покупатель в соответствии с применимыми правилами.</p>
<h3>Недостатки товара и гарантийные обращения</h3><p>Сообщите о недостатке на <a href="mailto:{email}">{email}</a> или письменно по адресу: {returns}. Укажите товар, дату покупки, описание недостатка и выбранное требование. Требования рассматриваются по статьям 18–24 Закона РФ «О защите прав потребителей»; применяются предусмотренные законом сроки и особенности технически сложных товаров. Обращение к производителю или в сервисный центр не лишает покупателя права предъявить законное требование продавцу.</p>
<h2>Поставки организациям и предпринимателям</h2><p>Для приобретения в предпринимательских целях условия поставки, приёмки, оплаты, гарантии и возврата определяются договором и применимыми нормами гражданского законодательства. Потребительские правила не подменяют условия такого договора.</p>'''
